WITH v(kind,k1,k2,k3,k4,k5,k6,k7,k8) AS (SELECT 'schema:T1', cid, name, type, [notnull], COALESCE(dflt_value,'<null>'), pk, NULL, NULL FROM pragma_table_info('T1') UNION ALL SELECT 'schema:T2', cid, name, type, [notnull], COALESCE(dflt_value,'<null>'), pk, NULL, NULL FROM pragma_table_info('T2') UNION ALL SELECT 'data:T1', NULL, B, C, D, E, F, G, H FROM T1 UNION ALL SELECT 'data:T2', A, B, C, NULL, NULL, NULL, NULL, NULL FROM T2) SELECT kind,k1,k2,k3,k4,k5,k6,k7,k8 FROM v ORDER BY kind,k1,k2,k3;